impl<T: gx::Real> Point<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[2] * x[2];
        t0
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (7 mul, 0 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Point<(), T> {
        let x = self.c;
        let t0 = x[2] * x[2];
        let t1 = x[2] * t0;
        let t2 = x[2] * t1;
        let t3 = t2.recip();
        let t4 = t0 * t3;
        let t5 = x[0] * t4;
        let t6 = x[1] * t4;
        let t7 = x[2] * t4;
        let t8 = -t5;
        let t9 = -t6;
        let t10 = -t7;
        Point::from_coeffs([t8, t9, t10])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[2] * x[2];
        let s0 = (p0).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        gx::Unit::new_unchecked(Point::from_coeffs([t0, t1, t2]))
    }

    /// The exponential, a unit versor: `exp(B) = C(BÂ²) + S(BÂ²) B` with `BÂ²` a Study number.
    #[inline]
    #[allow(unused_variables)]
    pub fn exp(self) -> gx::Unit<Motor<(), T>> {
        T::vectorize(#[inline(always)] move || {
        let x = self.c;
        let p0 = x[2] * x[2];
        let p1 = -p0;
        let [c0, c1, s0, s1] = gx::study::exp_coeffs_rotation(p1, T::from_i64(0));
        let t0 = x[2] * s0;
        let t1 = x[0] * s0;
        let t2 = x[1] * s0;
        gx::Unit::new_unchecked(Motor::from_coeffs([c0, t0, t1, t2]))
        })
    }

}

impl<T: gx::Coef> gx::NewtonStep for Point<(), T> {
    /// `x (3 â x ~x) / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[2] * x[2];
        let t2 = (-t0).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t3 = x[0] * t2;
        let t4 = x[1] * t2;
        let t5 = x[2] * t2;
        let t6 = t3 * T::from_ratio(3, 2);
        let t7 = t4 * T::from_ratio(3, 2);
        let t8 = t5 * T::from_ratio(3, 2);
        Point::from_coeffs([t6, t7, t8])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

