impl<T: gx::Real> Rotor<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t2 = x[0].mul_add(x[0], t1);
        t2
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (10 mul, 3 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Rotor<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t3 = t0 * t1;
        let t4 = t1 * t1;
        let t5 = t0.mul_add(t0, t4);
        let t7 = t3.mul_add(T::from_i64(2), t5);
        let t8 = t7.recip();
        let t10 = t1 * t8;
        let t11 = t0.mul_add(t8, t10);
        let t12 = x[0] * t11;
        let t13 = x[1] * t11;
        let t14 = -t13;
        Rotor::from_coeffs([t12, t14])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p2 = x[0].mul_add(x[0], p1);
        let s0 = (p2).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        gx::Unit::new_unchecked(Rotor::from_coeffs([t0, t1]))
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline(always)]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Rotor::from_coeffs(c).normalized()
    }

}

impl<T: gx::Coef> gx::NewtonStep for Rotor<(), T> {
    /// `x (3 â x ~x) / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t2 = x[0].mul_add(x[0], t1);
        let t3 = x[0] * t2;
        let t4 = x[1] * t2;
        let t6 = x[0] * T::from_ratio(3, 2);
        let t7 = (-t3).mul_add(T::from_ratio(1, 2), t6);
        let t9 = x[1] * T::from_ratio(3, 2);
        let t10 = (-t4).mul_add(T::from_ratio(1, 2), t9);
        Rotor::from_coeffs([t7, t10])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

impl<T: gx::Real> gx::Log<Point<(), T>> for gx::Unit<Rotor<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Point<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.into_inner().c;
        let p0 = x[1] * x[1];
        let p1 = -p0;
        let [h0, h1] = gx::study::log_coeffs_rotation((x[0], T::from_i64(0)), (p1, T::from_i64(0)));
        let t0 = x[1] * h0;
        Point::from_coeffs([T::from_i64(0), T::from_i64(0), t0])
        })
    }
}

