    /// The identity map on `Multivector`: a `Multivector` with one open `Multivector` slot.
    #[inline(always)]
    pub fn slot() -> Multivector<(Multivector,), T> {
        Multivector { c: core::array::from_fn(|i| core::array::from_fn(|j| if i == j { T::one() } else { T::zero() })) }
    }

    /// Coefficient of `1`.
    #[inline(always)]
